#include <stdint.h>
#include "stm32f103x8.h"
#include "GPIO.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
#warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

void clock_init(void) {
    // Enable GPIOB clock using your header macro
    RCC_GPIO_B_CLK_EN();
}
void wait_ms(uint32_t time){
	uint32_t i, j;
	for(i = 0; i < time; i++){
		for(j = 0; j < 255; j++);
	}
}
void peripherals_init(void) {
    GPIO_PinConfig_t PinCfg;

    // Configure PB0, PB1, PB10 (LEDs) and PB11 (Buzzer) as Output Push-Pull, 2 MHz
    PinCfg.GPIO_MODE = GPIO_MODE_OUTPUT_PP;
    PinCfg.GPIO_Output_Speed = GPIO_SPEED_2M;

    // Initialize LED 1 on PB0
    PinCfg.GPIO_PinNumber = GPIO_PIN_0;
    MCAL_GPIO_Init(GPIO_B, &PinCfg);

    // Initialize LED 2 on PB1
    PinCfg.GPIO_PinNumber = GPIO_PIN_1;
    MCAL_GPIO_Init(GPIO_B, &PinCfg);

    // Initialize LED 3 on PB10
    PinCfg.GPIO_PinNumber = GPIO_PIN_10;
    MCAL_GPIO_Init(GPIO_B, &PinCfg);

    // Initialize Buzzer on PB11
    PinCfg.GPIO_PinNumber = GPIO_PIN_11;
    MCAL_GPIO_Init(GPIO_B, &PinCfg);
}


int main(void) {
    clock_init();
    peripherals_init();

    while(1) {
        // --- Step 1: Turn ON LED 1 (PB0), others OFF ---
        MCAL_GPIO_WritePin(GPIO_B, GPIO_PIN_0, GPIO_PIN_SET);
        MCAL_GPIO_WritePin(GPIO_B, GPIO_PIN_1, GPIO_PIN_RESET);
        MCAL_GPIO_WritePin(GPIO_B, GPIO_PIN_10, GPIO_PIN_RESET);
        MCAL_GPIO_WritePin(GPIO_B, GPIO_PIN_11, GPIO_PIN_RESET);
        wait_ms(500);

        // --- Step 2: Turn ON LED 2 (PB1), others OFF ---
        MCAL_GPIO_WritePin(GPIO_B, GPIO_PIN_0, GPIO_PIN_RESET);
        MCAL_GPIO_WritePin(GPIO_B, GPIO_PIN_1, GPIO_PIN_SET);
        MCAL_GPIO_WritePin(GPIO_B, GPIO_PIN_10, GPIO_PIN_RESET);
        MCAL_GPIO_WritePin(GPIO_B, GPIO_PIN_11, GPIO_PIN_RESET);
        wait_ms(500);

        // --- Step 3: Turn ON LED 3 (PB10), others OFF ---
        MCAL_GPIO_WritePin(GPIO_B, GPIO_PIN_0, GPIO_PIN_RESET);
        MCAL_GPIO_WritePin(GPIO_B, GPIO_PIN_1, GPIO_PIN_RESET);
        MCAL_GPIO_WritePin(GPIO_B, GPIO_PIN_10, GPIO_PIN_SET);
        MCAL_GPIO_WritePin(GPIO_B, GPIO_PIN_11, GPIO_PIN_RESET);
        wait_ms(500);

        // --- Step 4: Turn ON Buzzer (PB11) for a tick/pulse, LEDs OFF ---
        MCAL_GPIO_WritePin(GPIO_B, GPIO_PIN_0, GPIO_PIN_RESET);
        MCAL_GPIO_WritePin(GPIO_B, GPIO_PIN_1, GPIO_PIN_RESET);
        MCAL_GPIO_WritePin(GPIO_B, GPIO_PIN_10, GPIO_PIN_RESET);
        MCAL_GPIO_WritePin(GPIO_B, GPIO_PIN_11, GPIO_PIN_SET);
        wait_ms(500);
        // Turn off buzzer before repeating the loop
        MCAL_GPIO_WritePin(GPIO_B, GPIO_PIN_11, GPIO_PIN_RESET);
    }
}
